import logging
import os
import subprocess
from abc import ABC, abstractmethod
from datetime import datetime

from taf.sw.syslog.util import generate_random_string


class FileWriter:
    def __new__(
        cls, log_dir: str, log_name: str, file_limit: int, add_line_number: bool = False
    ):
        if file_limit > 0:
            return MultiFileWriter(log_dir, log_name, file_limit, add_line_number)
        return SingleFileWriter(log_dir, log_name, add_line_number)


class BaseFileWriter(ABC):
    """Base class for File Writers - objects responsible for creating and writing data to log files."""

    def __init__(self, add_line_number: bool):
        self._log_size = 0
        self._create_log_dir()
        self._remove_old_logs()
        self._add_line_number = add_line_number
        self._line_count = 1
        self._log = self._create_file_logger(self.log_path)

    @property
    @abstractmethod
    def log_path(self):
        """Return path to log file."""

    @abstractmethod
    def write(self, data):
        """Write data to log file."""

    @abstractmethod
    def _remove_old_logs(self):
        """Remove log directory."""

    @abstractmethod
    def _create_log_dir(self):
        """Create log directory."""

    def clean_log(self):
        """Clean log file."""
        open(self.log_path, "w").close()

    def _create_file_logger(self, log_path: str) -> logging.Logger:
        log = logging.getLogger(generate_random_string())
        log.addHandler(logging.FileHandler(log_path))
        log.setLevel(logging.DEBUG)
        return log

    def _create_dir(self, log_dir: str) -> None:
        os.makedirs(log_dir, exist_ok=True)

    def _write(self, data: str):
        lines: list[str] = self._filter_characters(data.split("\n"))
        for line in lines:
            line = f"{self._get_timestamp()} {line}"
            if self._add_line_number:
                line_number = str(self._line_count).zfill(6)
                self._line_count += 1
                line = f"{line_number} {line}"
            self._log_size += len(line)
            self._log.debug(line)

    def _filter_characters(self, data: list[str]) -> list[str]:
        filtered_lines = []
        for line in data:
            line = line.replace(chr(13), "").replace(chr(10), "").replace(chr(0), "")
            if line.strip():
                filtered_lines.append(line)
        return filtered_lines

    def _get_timestamp(self) -> str:
        return datetime.now().strftime("%d.%m %H:%M:%S.%f")

    def _remove_files(self, cwd: str, file_pattern: str) -> None:
        subprocess.call(f"rm -rf {file_pattern}", shell=True, cwd=cwd)


class MultiFileWriter(BaseFileWriter):
    """
    File writer object used when user specifies `file_limit` during FileWriter creation.
    This writer will create new log files when the current one exceeds the size limit in bytes.

    :param log_dir: Directory where the log file should be located.
    :type log_dir: str
    :param log_name: Base log file name that will be used to create new log file names.
    :type log_name: str
    :param file_limit: File size limit in bytes. All of created log files will be limited to this size.
    :type file_limit: int
    :param add_line_number: Flag indicating whether line numbers should be added to log entries.
    :type add_line_number: bool
    """

    def __init__(
        self, log_dir: str, log_name: str, file_limit: int, add_line_number: bool
    ):
        self._log_dir = log_dir
        self._log_limit = file_limit
        self._log_number = 0
        self._log_base_name, self._log_ext = self._generate_log_name_parts(log_name)
        self._log_path = None
        super().__init__(add_line_number)

    @property
    def log_path(self):
        return self._get_log_path()

    def write(self, data: str) -> None:
        if not self._log or self._log_size >= self._log_limit:
            self._log_path = self._create_log_path()
            self._log = self._create_file_logger(self._log_path)
            self._log_size = 0
        self._write(data)

    def _generate_log_name_parts(self, log_name: str) -> tuple[str, str]:
        result = log_name.rsplit(".", maxsplit=1)
        if len(result) > 1:
            return result[0], f".{result[1]}"
        return result[0], ""

    def _create_log_dir(self) -> None:
        self._create_dir(self._log_dir)

    def _create_log_path(self) -> str:
        self._log_number += 1
        return self._get_log_path()

    def _get_log_path(self) -> str:
        timestamp = datetime.now().strftime("%Y%m%d%H%M%S")
        name = f"{self._log_base_name}_{timestamp}_{self._log_number}{self._log_ext}"
        return os.path.join(self._log_dir, name)

    def _remove_old_logs(self) -> None:
        self._remove_files(self._log_dir, f"{self._log_base_name}_*{self._log_ext}")


class SingleFileWriter(BaseFileWriter):
    """
    File writer object used when user does not specify `file_limit` during FileWriter creation.
    This writer will write all data to a single log file.

    :param log_dir: The directory where the log file will be stored.
    :type log_dir: str
    :param log_name: The name of the log file.
    :type log_name: str
    :param add_line_number: Flag indicating whether to add line numbers to the log file.
    :type add_line_number: bool
    """

    def __init__(self, log_dir: str, log_name: str, add_line_number: bool):
        self._log_dir = log_dir
        self._log_name = log_name
        self._log_path = os.path.join(log_dir, log_name)
        super().__init__(add_line_number)

    @property
    def log_path(self):
        return self._log_path

    def write(self, data: str) -> None:
        if not self._log:
            self._log = self._create_file_logger(self._log_path)
        self._write(data)

    def _create_log_dir(self) -> None:
        """Create the log directory if it doesn't exist."""
        self._create_dir(self._log_dir)

    def _remove_old_logs(self) -> None:
        """Remove old log files from the log directory."""
        self._remove_files(self._log_dir, self._log_name)
